package com.mitcampus.ams.entity;
import jakarta.persistence.*;import java.time.*;
@Entity @Table(name="APPOINTMENTS") public class Appointment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="APPOINTMENT_ID") public Long id; @ManyToOne(optional=false) @JoinColumn(name="STUDENT_ID") public Student student; @ManyToOne(optional=false) @JoinColumn(name="OFFICIAL_ID") public Official official; public String purpose; @Column(length=2000) public String description; @Column(name="REQUESTED_DATE") public LocalDate requestedDate; @Column(name="PREFERRED_TIME") public LocalTime preferredTime; @Column(name="ALLOCATED_DATE") public LocalDate allocatedDate; @Column(name="ALLOCATED_TIME") public LocalTime allocatedTime; public String status="PENDING"; @Column(length=2000) public String remarks; @Column(name="CREATED_AT") public LocalDateTime createdAt=LocalDateTime.now(); @Column(name="UPDATED_AT") public LocalDateTime updatedAt=LocalDateTime.now(); }
